<script>
  import { onMount } from 'svelte';
  import { makeReceipt } from './receipt.js';
  let page=$state('home'),step=$state('choose'),choice=$state(''),receipt=$state(null),busy=$state(false),error=$state('');
  let persistent=$state(false),configured=$state(false),lookup=$state(''),lookupResult=$state('');
  const options=[{id:'garden',name:'A neighborhood garden',detail:'More space for growing, gathering, and the living world.'},{id:'library',name:'A library of things',detail:'Share tools, equipment, and the things we only need sometimes.'},{id:'assembly',name:'A citizens’ assembly',detail:'Make room for neighbors to deliberate and decide together.'},{id:'abstain',name:'I choose to abstain',detail:'Participation can include choosing none of these options.'}];
  onMount(async()=>{try{const response=await fetch('/api/config');if(!response.ok)throw Error();const config=await response.json();persistent=config.persistent;configured=true;}catch{configured=false;}});
  function navigate(next){page=next;error='';window.scrollTo({top:0,behavior:'smooth'});}
  async function cast(){
    busy=true;error='';
    try{
      let record=await makeReceipt(choice);
      if(persistent){const response=await fetch('/api/receipts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({commitment:record.commitment})});const body=await response.json();if(!response.ok)throw Error(body.error||'Could not record the receipt.');record=body;}
      record={...record,persistent};
      receipt=record;
      try{localStorage.setItem('vote-anyway-receipt',JSON.stringify(record));}catch{/* A downloadable receipt remains available when storage is blocked. */}
      step='receipt';
    }catch(e){error=e.message||'Could not create a receipt. Please try again.';}finally{busy=false;}
  }
  async function verify(){
    lookupResult='';error='';busy=true;
    try{
      const hash=lookup.trim().toLowerCase();
      if(!/^[a-f0-9]{64}$/.test(hash))throw Error('Enter the full 64-character receipt code.');
      if(persistent){const response=await fetch('/api/receipts/'+hash);const body=await response.json();if(!response.ok)throw Error(body.error||'Could not check this receipt.');lookupResult='Found in the practice receipt register. Recorded '+new Date(body.createdAt).toLocaleString()+'.';}
      else{let saved;try{saved=JSON.parse(localStorage.getItem('vote-anyway-receipt')||'null');}catch{}if(saved?.commitment!==hash)throw Error('This receipt is not saved in this browser. Browser-only receipts cannot be checked on another device.');lookupResult='Found in this browser’s practice record. This is a local check, not confirmation from a public register.';}
    }catch(e){error=e.message;}finally{busy=false;}
  }
  function download(){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}));a.href=url;a.download='vote-anyway-practice-receipt.json';a.click();URL.revokeObjectURL(url);}
</script>

<svelte:head><title>Vote Anyway — {page==='home'?'Democracy, more often.':page==='ballot'?'Practice ballot':page==='verify'?'Check a receipt':'The experiment'}</title></svelte:head>
<div class="notice">AN OPEN EXPERIMENT IN DEMOCRACY <span>Independent. Unofficial. In progress.</span></div>
<header>
  <button class="brand" onclick={()=>navigate('home')} aria-label="Vote Anyway home"><span class="mark">v<span>↗</span></span>vote anyway<span class="brand-dot">.</span></button>
  <nav aria-label="Main navigation"><a href="/essay.html">Read the essay</a><button class:active={page==='about'} onclick={()=>navigate('about')}>The experiment</button><button class:active={page==='verify'} onclick={()=>navigate('verify')}>Check a receipt</button><a href="https://github.com/anselm/vote-anyway" target="_blank" rel="noreferrer">GitHub ↗</a></nav>
</header>
<main>
{#if page==='home'}
  <section class="hero">
    <div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> A WORKING IDEA, OPEN TO EVERYONE</div><h1>Democracy,<br/>more <em>often.</em></h1><p class="intro">What if having a say were as simple as sending a message?</p><p class="muted hero-description">Vote Anyway is an experiment in making collective decisions more accessible, more frequent, and open to inspection. An essay and a working prototype, growing together.</p><div class="actions"><button class="primary" onclick={()=>{step='choose';choice='';navigate('ballot');}}>Try a practice ballot <span>↗</span></button><button class="text-link" onclick={()=>navigate('about')}>Explore the idea ↓</button></div><p class="fine">No account needed. About a minute. Entirely unofficial.</p></div>
    <div class="hero-art" aria-hidden="true"><div class="art-grid"></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="ballot-paper"><span class="paper-kicker">YOUR VOICE</span><div class="paper-rule"></div><div class="paper-choice"><span>✓</span><i></i></div><div class="paper-choice"><span></span><i></i></div><div class="paper-choice"><span></span><i></i></div><div class="paper-bottom">A PART IN THE WHOLE. <b>↗</b></div></div><div class="art-label"><span class="live-dot"></span> MANY VOICES. SHARED POSSIBILITIES.</div><div class="art-corner">01 / AN EXPERIMENT</div></div>
  </section>
  <section class="principles"><article><span class="number">01</span><h2>A say, more often.</h2><p>Explore what changes when participation fits into everyday life.</p></article><article><span class="number">02</span><h2>Trust you can inspect.</h2><p>Build toward decisions whose records can be checked independently.</p></article><article><span class="number">03</span><h2>Ideas put into practice.</h2><p>Let working experiments inform the argument—and the next experiment.</p></article></section>
  <section class="lower"><div><div class="eyebrow">THE FIRST STEP</div><h2>Start small.<br/>Ask bigger questions.</h2></div><div><p>This first release lets you try a fictional ballot and check a receipt. It is a starting point for the interface and infrastructure.</p><p class="muted">Next come identity, eligibility, encrypted ballots, and independent verification. The code and the questions are open.</p><button class="text-link" onclick={()=>navigate('about')}>See what’s built and what’s next ↗</button></div></section>
{:else if page==='ballot'}
  <section class="workspace"><button class="back" onclick={()=>navigate('home')}>← Back to the experiment</button><div class="eyebrow">PRACTICE ELECTION / 001</div><h1 class="page-title">A little more<br/><em>collective possibility.</em></h1><p class="intro">What would you bring to a neighborhood?</p><p class="muted">A fictional question to explore the voting experience. There is no real election or tally.</p>
  <div class="step-line"><span class:current={step==='choose'}>01 Choose</span><span class:current={step==='review'}>02 Review</span><span class:current={step==='receipt'}>03 Receipt</span></div>
  {#if step==='choose'}<fieldset><legend>Choose one option</legend>{#each options as option}<label class="option" class:selected={choice===option.id}><input type="radio" name="choice" value={option.id} bind:group={choice}/><div><strong>{option.name}</strong><p>{option.detail}</p></div></label>{/each}</fieldset><button class="primary" disabled={!choice} onclick={()=>step='review'}>Review my choice <span>→</span></button>
  {:else if step==='review'}<div class="panel"><div class="eyebrow">YOUR PRACTICE CHOICE</div><h2>{options.find(o=>o.id===choice)?.name}</h2><p>Your selection stays in your browser. We create a randomized digital fingerprint of it; {persistent?'only that fingerprint is sent to the practice register.':'the receipt is saved only on this device.'}</p><p class="fine">This tests receipt creation, not secret-ballot security, voter eligibility, or a verifiable tally. You can practice more than once.</p></div><div class="actions"><button class="primary" disabled={busy} onclick={cast}>{busy?'Creating receipt…':'Create practice receipt'} <span>↗</span></button><button class="text-link" disabled={busy} onclick={()=>step='choose'}>Change choice</button></div>
  {:else}<div class="panel receipt"><span class="success-icon">✓</span><div class="eyebrow">PRACTICE COMPLETE</div><h2>Your voice starts somewhere.</h2><p>{receipt.persistent?'Your receipt fingerprint is in the practice register.':'Your practice receipt is saved in this browser when browser storage is available.'}</p><label for="receipt-code">Your receipt code</label><code id="receipt-code">{receipt.commitment}</code><p class="fine">This fingerprint does not reveal your selection. Receipt inclusion alone does not prove a ballot was cast or tallied correctly.</p><div class="actions"><button class="primary" onclick={()=>{lookup=receipt.commitment;lookupResult='';navigate('verify');}}>Check this receipt →</button><button class="text-link" onclick={download}>Download receipt ↓</button></div></div>{/if}
  {#if error}<p class="error" role="alert">{error}</p>{/if}<p class="storage-note">{configured?(persistent?'Practice register connected. Only fingerprints are stored.':'Browser-only practice. Database connection pending.'):'Service connection unavailable. Practice receipts stay in your browser.'}</p></section>
{:else if page==='verify'}
  <section class="workspace"><button class="back" onclick={()=>navigate('home')}>← Home</button><div class="eyebrow">FOLLOW THE RECORD</div><h1 class="page-title">A receipt.<br/><em>A place to begin.</em></h1><p class="intro">Check a practice receipt.</p><p class="muted">Paste the fingerprint from your receipt. {persistent?'We’ll look it up in the practice register.':'This release checks receipts saved in this browser.'}</p><form class="panel" onsubmit={(event)=>{event.preventDefault();verify();}}><label for="lookup">Receipt code</label><input id="lookup" class="code-input" bind:value={lookup} placeholder="Enter your 64-character receipt code" autocomplete="off" spellcheck="false" required/><button class="primary" disabled={busy}>{busy?'Checking…':'Find my receipt'} <span>→</span></button>{#if lookupResult}<p class="result" role="status">✓ {lookupResult}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</form><p class="fine">A receipt lookup confirms a fingerprint exists. It does not verify voter eligibility, ballot intent, or an election result.</p></section>
{:else}
  <section class="workspace about"><button class="back" onclick={()=>navigate('home')}>← Home</button><div class="eyebrow">THEORY ↔ ACTION</div><h1 class="page-title">An argument.<br/><em>And an experiment.</em></h1><p class="intro">What becomes possible when collective decisions are easier to make?</p><p>Voting sits within a wider system: sensing what is happening, deliberating about what matters, deciding together, acting, and learning from the result. A better ballot is one part of that picture.</p><p>Vote Anyway brings an essay and a software experiment into the same place. The essay explores secure internet voting and its democratic possibilities. The prototype gives us something concrete to question, inspect, and improve.</p><div class="roadmap"><div class="eyebrow">WHERE WE ARE</div><article><span class="status">NOW</span><div><h2>A working beginning</h2><p>A mobile practice ballot, randomized receipt fingerprints, receipt checking, and a PostgreSQL storage adapter. The practice interface deliberately collects no identity or actual election ballot.</p></div></article><article><span class="status next">NEXT</span><div><h2>Identity, eligibility, verification</h2><p>Connect attest.monster, define election participation policies, and select a reviewed cryptographic protocol. Keep identity, eligibility decisions, encrypted ballots, and public audit records separate.</p></div></article><article><span class="status next">EXPLORE</span><div><h2>More ways to decide</h2><p>Provisional ballots and eligibility adjudication. Social trust graphs inspired by Advogato. Ranked and approval voting. Later, delegation and liquid democracy.</p></div></article></div><h2>The companion essay: Vote Anyway</h2><p>The core essay makes the persuasive argument. Linked appendices carry the technical detail, citations, previous work, and implementation questions. The original first draft has been recovered from the project conversation. Read it with its original wording and links.</p><a class="primary inline" href="https://github.com/anselm/vote-anyway" target="_blank" rel="noreferrer">Follow the work on GitHub ↗</a> <a class="primary inline" href="/essay.html">Read the original essay ↗</a></section>
{/if}
</main>
<footer><button class="brand small" onclick={()=>navigate('home')}>vote anyway.</button><p>An open experiment. A work in progress.</p><span>BUILT IN PUBLIC ↗</span></footer>
